package com.paymentplatform.reconciliation_service.api;
import com.paymentplatform.reconciliation_service.domain.ExternalStatementService;import com.paymentplatform.reconciliation_service.security.ServiceActor;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;import java.util.UUID;
@RestController public class ExternalStatementController {
 private final ExternalStatementService service;public ExternalStatementController(ExternalStatementService service){this.service=service;}
 @PostMapping("/internal/v1/external-statements") ResponseEntity<?> reconcile(@AuthenticationPrincipal Jwt jwt,@Valid @RequestBody ExternalStatementService.Request request){return ResponseEntity.status(201).cacheControl(CacheControl.noStore()).body(service.reconcile(jwt.getClaimAsString("integrator_id"),ServiceActor.requireService(jwt),request,jwt.getTokenValue()));}
 @GetMapping("/internal/v1/external-statements/{id}") ResponseEntity<?> get(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID id){ServiceActor.requireService(jwt);return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(service.get(jwt.getClaimAsString("integrator_id"),id));}
 @GetMapping("/internal/v1/external-statements/{id}/investigations") ResponseEntity<?> notes(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID id,@RequestParam(required=false) UUID after,@RequestParam(defaultValue="50") @jakarta.validation.constraints.Min(1) @jakarta.validation.constraints.Max(100) int limit){ServiceActor.requireService(jwt);return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(service.notes(jwt.getClaimAsString("integrator_id"),id,after,limit));}
 @PostMapping("/internal/v1/external-statements/{id}/investigations") ResponseEntity<?> investigate(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID id,@Valid @RequestBody ExternalStatementService.Investigation request){String actor=jwt.getSubject();if(!"operator".equals(jwt.getClaims().get("actor_type"))||actor==null||actor.isBlank()||actor.length()>128||!actor.equals(actor.strip())||actor.chars().anyMatch(Character::isISOControl))throw new ApiException(HttpStatus.FORBIDDEN,"OPERATOR_REQUIRED","A signed operator is required.");service.investigate(jwt.getClaimAsString("integrator_id"),actor,id,request,jwt.getTokenValue());return ResponseEntity.noContent().cacheControl(CacheControl.noStore()).build();}
}
